de seguridad distinto de texto inicial editable Tu pago está protegido con encriptación de extremo a extremo; mostrar claim solo con evidencia autorizada. Sello PCI DSS configurable, inicial apagado, mostrar solo cuando parámetro autorizado y evidencia vigente, no afirmar nivel específico ni marca. Parámetro {param:CLIENT.PAYMENT_PCI_BADGE_ENABLED}. Binding runtime pendiente; no modifica IG, fuentes oficiales ni legadas.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/331","solicitante":"Cristhian / Claude S22-AU"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"au_success_security"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"au_provider_security_name_visible"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"au_provider_security_logo_visible"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_security_copy_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_security_copy_not_editable"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_pci_shown_without_config"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_pci_shown_without_evidence"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_encryption_claim_unverified"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"au_success_security":true,"au_provider_security_name_visible":false,"au_provider_security_logo_visible":false,"au_security_copy_wrong":false,"au_security_copy_not_editable":false,"au_pci_shown_without_config":false,"au_pci_shown_without_evidence":false,"au_encryption_claim_unverified":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"au_success_security":true,"au_provider_security_name_visible":true,"au_provider_security_logo_visible":false,"au_security_copy_wrong":false,"au_security_copy_not_editable":false,"au_pci_shown_without_config":false,"au_pci_shown_without_evidence":